import test from 'node:test';
import assert from 'node:assert/strict';
import { mod } from '../src/calc.js';

test('mod returns the remainder', () => {
  assert.equal(mod(7, 3), 1);
});

test('mod with exact divisor returns 0', () => {
  assert.equal(mod(6, 3), 0);
});

test('mod by 0 returns NaN', () => {
  assert.ok(Number.isNaN(mod(5, 0)));
});

